def followup_view(inputs, prior):
    packet=inputs.get('twelfth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twelfth period packet changed')
    if prior is None or prior['counts']['after']!=90 or packet['prior_digest']!=digest(prior):raise ValueError('twelfth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twelfth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=21 or len(packet['sources'])!=21 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twelfth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twelfth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twelfth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twelfth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twelfth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twelfth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('twelfth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('twelfth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('twelfth period quarter changed')
        if row['reported_quarter_yuan']is not None and D(row['reported_quarter_yuan'])!=nine-h:raise ValueError('twelfth period reported quarter changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('twelfth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twelfth period windows changed')
    return {'through':'2026-11-19','title':'完成了交易，原风险和经营怎样更新？','answer':'明德已过户并付清对价，期初交割待办可关闭；人福出售款已收，期间报告将原预计损益更新为5.14亿元，但归母增长与扣非下降同时存在。金花抵偿安排已补正，终局仲裁仍有效且预计负债已入损益；九鼎新签合同增加仍未转成盈利现金。把实际履约、法律效力、会计处理和年度警示分开，才能更新原判断。','chains':CHAINS,'financial_bridge':FINANCIAL,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':21,'new_files':19,'reused_files':2,'pages':802,'new_pages':639,'viewed_pages':len(VISUAL),'initial_coverage':90,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'21份802页中19关键页视觉核对，不称全文已阅；其中2份163页已用于金花更正，本次不再当新增来源，另19份639页。160条期间目录不认证全部催化穷尽，6月30日补漏不当7月后事件。60窗口54满6未满、61个窗口股票端点跨渠道一致；不关闭人福7月3/31日历史报价差异。16半年算术中12与披露一致、4原表不适用仅另算；16季度差额14有直接披露、2现金为推算。原更正层及旧主题完整保留，已计提仲裁不重复扣净利润，旧保证金不当新现金；公告同窗不识别净因果，重复事项不增加经验验证。','method_promotions':0}
